import { createHash, randomUUID } from 'crypto'
import {
  existsSync,
  readdirSync,
  readFileSync,
  renameSync,
  unlinkSync,
  writeFileSync
} from 'fs'
import path from 'path'

/**
 * Integrity checks for the payloads SkipNet executes elevated.
 *
 * Every Zapret `.bat` / `winws.exe` / WinDivert driver and the TgWsProxy
 * binary is hashed in a checked-in manifest (`resources/binaries.sha256`,
 * sha256sum format). The manifest is generated by
 * `scripts/build-binary-manifest.mjs` at build time and re-generated by the
 * component updaters after a digest-verified download.
 *
 * The manifest is read from the *bundled resources tree*, which is either
 * `process.resourcesPath` (installed app, admin-only) or the repo
 * `resources/` folder in dev. Nothing is spawned without a successful check.
 */

export const MANIFEST_NAME = 'binaries.sha256'

/**
 * Extensions treated as executable payload. Used both to enforce manifest
 * coverage (`every executable in the component must be listed`) and by the
 * updaters to regenerate entries for a freshly installed bundle.
 */
const EXECUTABLE_EXTENSIONS = new Set([
  '.bat',
  '.cmd',
  '.com',
  '.cpl',
  '.dll',
  '.exe',
  '.js',
  '.msi',
  '.ps1',
  '.psm1',
  '.scr',
  '.sys',
  '.vbs'
])

const BLOCKED_PATH_SEGMENTS = new Set(['..'])

export class BinaryIntegrityError extends Error {
  constructor(message: string) {
    super(message)
    this.name = 'BinaryIntegrityError'
  }
}

function fail(detail: string): never {
  throw new BinaryIntegrityError(
    `Проверка целостности не пройдена: ${detail}. Переустановите SkipNet или обновите компонент.`
  )
}

/** Normalise and validate a manifest-relative path (`zapret/bin/winws.exe`). */
export function safeRelativePath(value: string): string {
  if (typeof value !== 'string') fail('путь в манифесте не является строкой')
  const raw = value.trim()
  if (!raw || raw.includes('\0')) fail(`недопустимый путь в манифесте: "${value}"`)
  if (path.isAbsolute(raw) || /^[a-zA-Z]:/.test(raw) || raw.startsWith('/') || raw.startsWith('\\')) {
    fail(`абсолютный путь запрещён: ${raw}`)
  }
  const segments = raw.replace(/\\/g, '/').split('/')
  if (segments.some((segment) => BLOCKED_PATH_SEGMENTS.has(segment))) {
    fail(`выход за пределы resources запрещён: ${raw}`)
  }
  const normalized = segments.filter((segment) => segment && segment !== '.').join('/')
  if (!normalized) fail(`пустой путь в манифесте: "${value}"`)
  return normalized
}

/** Resolve a manifest path below `resourcesRoot`, refusing traversal. */
export function resolveContainedPath(resourcesRoot: string, relativePath: string): string {
  const root = path.resolve(resourcesRoot)
  const normalized = safeRelativePath(relativePath)
  const absolute = path.resolve(root, ...normalized.split('/'))
  if (absolute !== root && !absolute.startsWith(root + path.sep)) {
    fail(`выход за пределы resources запрещён: ${relativePath}`)
  }
  return absolute
}

export function manifestPath(resourcesRoot: string): string {
  return path.join(path.resolve(resourcesRoot), MANIFEST_NAME)
}

/** Parse sha256sum output: `<64hex>  <path relative to resources/>`. */
export function parseManifestText(text: string): Record<string, string> {
  const entries: Record<string, string> = Object.create(null)
  const lines = text.split(/\r?\n/)
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim()
    if (!line || line.startsWith('#')) continue
    const match = line.match(/^([0-9a-fA-F]{64}) [ *](.+)$/)
    if (!match) fail(`некорректная строка ${i + 1} в ${MANIFEST_NAME}`)
    const relative = safeRelativePath(match[2].trim())
    const digest = match[1].toLowerCase()
    const previous = entries[relative]
    if (previous && previous !== digest) {
      fail(`противоречивые хеши для ${relative} в ${MANIFEST_NAME}`)
    }
    entries[relative] = digest
  }
  if (Object.keys(entries).length === 0) fail(`${MANIFEST_NAME} пуст`)
  return entries
}

export function serializeManifest(entries: Record<string, string>): string {
  return Object.keys(entries)
    .sort()
    .map((relative) => {
      const digest = String(entries[relative] ?? '').toLowerCase()
      if (!/^[0-9a-f]{64}$/.test(digest)) fail(`некорректный хеш для ${relative}`)
      return `${digest}  ${safeRelativePath(relative)}`
    })
    .join('\n') + '\n'
}

export function readManifestOrNull(resourcesRoot: string): Record<string, string> | null {
  const file = manifestPath(resourcesRoot)
  if (!existsSync(file)) return null
  try {
    return parseManifestText(readFileSync(file, 'utf8'))
  } catch {
    return null
  }
}

export function readManifest(resourcesRoot: string): Record<string, string> {
  const file = manifestPath(resourcesRoot)
  if (!existsSync(file)) {
    throw new BinaryIntegrityError(
      `Проверка целостности не пройдена: не найден ${MANIFEST_NAME}. Переустановите SkipNet.`
    )
  }
  let text: string
  try {
    text = readFileSync(file, 'utf8')
  } catch (e) {
    fail(`не удалось прочитать ${MANIFEST_NAME}: ${errorMessage(e)}`)
  }
  return parseManifestText(text)
}

export function writeManifestEntries(
  resourcesRoot: string,
  entries: Record<string, string>
): void {
  const root = path.resolve(resourcesRoot)
  const file = manifestPath(root)
  const temporary = `${file}.${randomUUID()}.tmp`
  try {
    writeFileSync(temporary, serializeManifest(entries), { encoding: 'utf8', flag: 'wx' })
    renameSync(temporary, file)
  } catch (e) {
    try {
      if (existsSync(temporary)) unlinkSync(temporary)
    } catch {
      /* noop */
    }
    throw new BinaryIntegrityError(
      `Не удалось обновить ${MANIFEST_NAME}: ${errorMessage(e)}`
    )
  }
}

function errorMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error)
}

function hashFile(absolutePath: string): string {
  try {
    return createHash('sha256').update(readFileSync(absolutePath)).digest('hex')
  } catch (e) {
    fail(`не удалось прочитать ${absolutePath}: ${errorMessage(e)}`)
  }
}

function verifyEntry(
  resourcesRoot: string,
  entries: Record<string, string>,
  relativePath: string
): void {
  const expected = entries[relativePath]
  if (!expected) {
    fail(`файл ${relativePath} не описан в ${MANIFEST_NAME}`)
  }
  const absolute = resolveContainedPath(resourcesRoot, relativePath)
  if (!existsSync(absolute)) {
    fail(`файл ${relativePath} не найден`)
  }
  const actual = hashFile(absolute)
  if (actual !== expected) {
    fail(`файл ${relativePath} изменён или повреждён (sha256 не совпадает)`)
  }
}

/** Verify one manifest entry against the file on disk. Throws on any mismatch. */
export function verifyFile(resourcesRoot: string, relativePath: string): void {
  const root = path.resolve(resourcesRoot)
  const relative = safeRelativePath(relativePath)
  const entries = readManifest(root)
  verifyEntry(root, entries, relative)
}

/**
 * Recursively list manifest-relative paths of every executable file inside
 * `componentDir`. Paths are relative to `resourcesRoot` so they can be written
 * into `binaries.sha256` verbatim.
 */
export function collectComponentExecutableFiles(
  resourcesRoot: string,
  componentDir: string
): string[] {
  const root = path.resolve(resourcesRoot)
  const dir = path.resolve(componentDir)
  const relativeDir = path.relative(root, dir).replace(/\\/g, '/')
  if (!relativeDir || relativeDir.startsWith('..') || path.isAbsolute(relativeDir)) {
    fail(`каталог компонента вне resources: ${componentDir}`)
  }
  const files: string[] = []
  const walk = (current: string): void => {
    for (const entry of readdirSync(current, { withFileTypes: true })) {
      // Never follow links/junctions: the app runs elevated and a junction
      // could point at an unrelated directory.
      if (entry.isSymbolicLink()) continue
      const absolute = path.join(current, entry.name)
      if (entry.isDirectory()) {
        walk(absolute)
        continue
      }
      if (!entry.isFile()) continue
      if (!EXECUTABLE_EXTENSIONS.has(path.extname(entry.name).toLowerCase())) continue
      const relative = path.relative(dir, absolute).replace(/\\/g, '/')
      files.push(`${relativeDir}/${relative}`)
    }
  }
  if (existsSync(dir)) walk(dir)
  return files.sort()
}

/**
 * Verify the complete Zapret bundle before anything from it is executed.
 *
 * 1. every executable file present on disk must be covered by the manifest;
 * 2. every manifest entry under the bundle must exist and match its hash;
 * 3. the fail-closed minimum (winws.exe, WinDivert64.sys, a strategy) must be
 *    present, so a stripped manifest cannot silently skip the check.
 */
export function verifyZapretBundle(bundleDir: string): void {
  const dir = path.resolve(bundleDir)
  const resourcesRoot = path.dirname(dir)
  const prefix = path.basename(dir)
  const entries = readManifest(resourcesRoot)

  const present = collectComponentExecutableFiles(resourcesRoot, dir)
  for (const relative of present) {
    if (!Object.prototype.hasOwnProperty.call(entries, relative)) {
      fail(`файл ${relative} не описан в ${MANIFEST_NAME}`)
    }
  }

  const prefixEntries = Object.keys(entries).filter((relative) =>
    relative.startsWith(`${prefix}/`)
  )
  if (prefixEntries.length === 0) {
    fail(`в ${MANIFEST_NAME} нет файлов компонента ${prefix}`)
  }
  for (const relative of prefixEntries) verifyEntry(resourcesRoot, entries, relative)

  for (const required of ['bin/winws.exe', 'bin/WinDivert64.sys']) {
    if (!Object.prototype.hasOwnProperty.call(entries, `${prefix}/${required}`)) {
      fail(`файл ${prefix}/${required} не описан в ${MANIFEST_NAME}`)
    }
  }
  const hasStrategy = prefixEntries.some((relative) =>
    /^[^/]+\.bat$/i.test(relative.slice(prefix.length + 1))
  )
  if (!hasStrategy) fail(`в ${prefix} нет ни одной стратегии .bat, описанной в ${MANIFEST_NAME}`)
}

/** Verify the TgWsProxy executable (and every executable shipped next to it). */
export function verifyTgwsBinary(binaryPath: string): void {
  const absolute = path.resolve(binaryPath)
  const dir = path.dirname(absolute)
  const resourcesRoot = path.dirname(dir)
  const relative = `${path.basename(dir)}/${path.basename(absolute)}`
  const entries = readManifest(resourcesRoot)

  for (const candidate of collectComponentExecutableFiles(resourcesRoot, dir)) {
    if (!Object.prototype.hasOwnProperty.call(entries, candidate)) {
      fail(`файл ${candidate} не описан в ${MANIFEST_NAME}`)
    }
  }
  verifyEntry(resourcesRoot, entries, safeRelativePath(relative))
}

/**
 * Re-hash `relativePaths` and persist them in the manifest. Entries of the
 * same top-level component that are no longer present are dropped, so a
 * component update cannot leave stale hashes behind.
 */
export function updateManifestEntries(
  resourcesRoot: string,
  relativePaths: readonly string[]
): void {
  const root = path.resolve(resourcesRoot)
  const relative = relativePaths.map((item) => safeRelativePath(item))
  const entries = readManifestOrNull(root) ?? {}

  const prefixes = new Set(relative.map((item) => item.split('/')[0]))
  for (const key of Object.keys(entries)) {
    if (prefixes.has(key.split('/')[0]) && !relative.includes(key)) delete entries[key]
  }

  for (const item of relative) {
    const absolute = resolveContainedPath(root, item)
    if (!existsSync(absolute)) fail(`файл ${item} не найден после установки`)
    entries[item] = hashFile(absolute)
  }

  writeManifestEntries(root, entries)
}
